async function seed() {
  const client = await pool.connect();
  try {
    for (const w of words) {
      await client.query(`
        INSERT INTO words (word, definition, part_of_speech, example_sentence, difficulty, is_custom)
        VALUES ($1, $2, $3, $4, $5, false)
        ON CONFLICT (word) DO NOTHING
      `, [w.word, w.definition, w.part_of_speech, w.example_sentence, w.difficulty]);
    }
    console.log(`Seed complete: ${words.length} words processed (duplicates skipped).`);
  } finally {
    client.release();
    await pool.end();
  }
}

seed().catch(err => {
  console.error('Seed failed:', err.message);
  process.exit(1);
});
